NAME = 'Est: Estonian Bible'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, Kristuse Jeesuse Apostel Jumala, meie Õnnistegija, ja Kristuse Jeesuse, meie lootuse käsul,',
        2: 'Timoteosele, oma tõelisele pojale usus. Armu, halastust, rahu Jumalalt Isalt ja Kristuselt Jeesuselt, meie Issandalt!',
        3: 'Nõnda kuidas ma Makedooniasse minnes sind õhutasin jääma kauemaks Efesosse, et mõningaid manitseda, et nad ei õpetaks teisiti',
        4: 'ega teeks tegemist tühjade juttudega ja lõpmatute suguvõsade üleslugemistega, mis tekitavad rohkem küsimusi kui Jumala majapidamisest arusaamist usus, nõnda tee.',
        5: 'Sest käskimise eesmärk on armastus puhtast südamest ja heast südametunnistusest ja silmakirjatsematust usust.',
        6: 'Neist on mõned ära taganenud ja kaldunud kõrvale tühja kõne poole,',
        7: 'tahtes olla käsuõpetajad, kuigi nad ei mõista seda, mida nad räägivad, ega seda, mida nad kindlasti väidavad.',
        8: 'Me ju teame, et käsk on hea, kui keegi seda käsitleb käsu kohaselt',
        9: 'ja peab meeles, et käsku pole seatud õigele, vaid ülekohtustele ja kangekaelseile, jumalakartmatuile ja patustele, õelatele ja roojastele, isatapjaile ja ematapjaile, mõrtsukaile,',
        10: 'hoorajaile, poisipilastajaile, inimesemüüjaile, valelikele, valevandujaile ja kõigele muule, mis käib õige õpetuse vastu -',
        11: 'õndsa Jumala au Evangeeliumi järgi, mis on usaldatud minu kätte.',
        12: 'Ma tänan teda, kes mind on teinud vägevaks, Kristust Jeesust, meie Issandat, et Ta mind on pidanud ustavaks, pannes mind Oma teenistusse,',
        13: 'ehk ma küll enne olin pilkaja ja tagakiusaja ja vägivaldne. Aga ma olen armu saanud, sest ma olin seda teinud teadmata, uskmatus meeles.',
        14: 'Meie Issanda arm aga on olnud üliväga suur usu ja armastusega, mis on Kristuses Jeesuses.',
        15: 'Ustav on see sõna ja kõigiti vastuvõetav, et Kristus Jeesus on tulnud maailma päästma patuseid, kelle seast mina olen suurim;',
        16: 'kuid sellepärast ma olen saanud armu, et Jeesus Kristus kõigepealt minus osutaks kõike Oma pikka meelt eeskujuks neile, kes veel edaspidi saavad usklikuks Temasse igaveseks eluks.',
        17: 'Aga ajastute Kuningale, kadumatule, nähtamatule, ainule Jumalale olgu au ja austus ajastute ajastuteni! Aamen.',
        18: 'Selle käsu ma panen su südamele, mu poeg Timoteos, vastavalt varemaile sinu kohta käivaile ennustustele, et sa nende varal võitleksid õilsat võitlust,',
        19: 'omades usku ja head südametunnistust, mille mõningad on tõuganud enesest ära ja on selle tõttu usu suhtes läinud põhja nagu laev.',
        20: 'Nende seast on Hümenaios ja Aleksandros, keda ma olen andnud saatana meelevalda, et nad karistuse all võõrduksid pilkamisest.',
    },
    2: {
        1: 'Ma manitsen siis nüüd kõigepealt tegema palveid, palvusi, eestpalveid, tänupalveid kõigi inimeste eest,',
        2: 'kuningate ja kõigi ülemate eest, et võiksime vaikset ja rahulikku elu elada kõiges jumalakartuses ja aususes.',
        3: 'Sest see on hea ja armas Jumala, meie Õnnistegija meelest,',
        4: 'Kes tahab, et kõik inimesed õndsaks saaksid ja tõe tunnetusele tuleksid.',
        5: 'Sest Jumal on üks, ka vahemees üks Jumala ja inimeste vahel, inimene Kristus Jeesus,',
        6: 'Kes andis Iseenese lunastushinnaks kõikide eest, et sellest antaks tunnistust parajail aegadel;',
        7: 'ja selle tarvis olen mina pandud kuulutajaks ja Apostliks - ma räägin tõtt Kristuses ega valeta mitte - paganate õpetajaks usus ja tões.',
        8: 'Ma tahan siis, et mehed palvetaksid igas kogumispaigas ja tõstaksid üles pühad käed ilma vihata ja kahtlemiseta;',
        9: 'nõndasamuti ka, et naised, viisakalt riietatud, endid ehiksid häbeliku ja mõistliku meelega, mitte juuksepalmikutega ega kullaga ega pärlitega ega kalliste riietega,',
        10: 'vaid heade tegudega, nõnda kui sobib naistele, kes endid tunnistavad jumalakartlikeks.',
        11: 'Naine õppigu vaiksel viisil, olles kõigiti alistuv.',
        12: 'Aga naisele ma ei luba õpetada ega valitseda mehe üle, vaid ta elagu vaikselt.',
        13: 'Sest Aadam loodi enne, siis Eeva;',
        14: 'ega Aadamat petetud, vaid naist peteti ja ta sattus üleastumisse,',
        15: 'aga ta saab õndsaks lastesünnitamise läbi, kui ta jääb ususse ja armastusse ning pühitsusse mõistliku meelega.',
    },
    3: {
        1: 'Ustav on see sõna: kui keegi püüab Koguduse ülevaataja ametisse, siis ta igatseb kaunist tööd.',
        2: 'Niisiis tuleb Koguduse ülevaatajal olla laitmatu, ühe naise mees, kaine, mõistlik, viisakas, külalislahke, osav õpetama;',
        3: 'mitte joodik, mitte riiakas, vaid leebe, rahunõudja, mitte rahaahne,',
        4: 'vaid kes oma maja hästi valitseb, kes oma lapsi peab sõnakuulmises kõige aususega.',
        5: 'Sest kui keegi iseenese maja ei oska juhtida, kuidas ta võib hoolt kanda Jumala Koguduse eest?',
        6: 'Ta ärgu olgu alles vastpöördunu, et ta ei läheks uhkeks ega langeks sama nuhtluse alla kui kurat.',
        7: 'Ka olgu tal hea tunnistus neilt, kes on väljaspool Kogudust, et ta ei satuks naeru alla ja kuradi köitesse.',
        8: 'Nõndasamuti tuleb ka abilistel olla ausad, mitte kahekeelsed, mitte joomamehed, mitte liigkasuvõtjad, vaid sellised,',
        9: 'kellel usu saladus on puhtas südametunnistuses.',
        10: 'Ent nad katsutagu enne läbi ja siis, kui nad on laitmatud, astugu nad ametisse.',
        11: 'Nõndasamuti olgu nende naised ausad, mitte keelepeksjad, kained, ustavad kõigis asjus.',
        12: 'Koguduse abilised olgu ühe naise mehed, kes oma lapsi ja oma peret hästi juhivad.',
        13: 'Sest need, kes on hästi pidanud oma ametit, saavutavad enestele kauni lugupidamise ja suure julguse usus, mis on Kristuses Jeesuses.',
        14: 'Seda kirjutan sulle, ehk ma küll loodan pea tulla sinu juurde,',
        15: 'et kui ma viibin, sa teaksid, kuidas tuleb käituda Jumala kojas, mis on elava Jumala Kogudus, tõe sammas ja alustugi.',
        16: 'Ja vastuvaieldamatu suur on jumalakartuse saladus: Jumal on avalikuks saanud lihas, õigeks mõistetud Vaimus, ilmunud inglitele, kuulutatud paganate seas, usutud maailmas, üles võetud ausse!',
    },
    4: {
        1: 'Aga Vaim ütleb selge sõnaga, et viimsel ajal mõned taganevad usust ja hoiavad eksitajate vaimude ja kurjade vaimude õpetuste poole,',
        2: 'valekuulutajate silmakirjaliku vagaduse tõttu, kes oma südametunnistusse otsekui tulise märgi on põletanud',
        3: 'ja keelavad abiellumast ning maitsmast rooga, mis Jumal on loonud selleks, et usklikud ja tõetundjad seda vastu võtaksid tänuga.',
        4: 'Sest kõik, mis Jumal on loonud, on hea, ja miski ei ole hüljatav, kui seda vastu võetakse tänuga.',
        5: 'Sest seda pühitsetakse Jumala sõna ja palve läbi.',
        6: 'Kui sa seda vendadele ette paned, oled sa Kristuse Jeesuse hea abiline ja toidad ennast usu ja hea õpetuse sõnadega, mida sa oled järginud.',
        7: 'Ent kõlvatut ja vananaiste vada väldi, aga harjuta ennast jumalakartuses.',
        8: 'Sest ihulikust harjutusest on pisut kasu; aga jumalakartusest on kasu kõigile asjadele ja sellel on käesoleva ja tulevase elu tõotus.',
        9: 'Ustav on see sõna ja kõigiti vastuvõetav.',
        10: 'Sest selleks me näeme vaeva ja võitleme, et me oleme lootnud elava Jumala peale, Kes on kõigi inimeste, iseäranis usklike, Õnnistegija.',
        11: 'Seda käsi ja õpeta!',
        12: 'Ükski ärgu põlaku sinu noorust, vaid ole usklikele eeskujuks sõnas, elus, armastuses, usus, meelepuhtuses.',
        13: 'Kuni ma tulen, ole hoolas ette lugema, manitsema ja õpetama.',
        14: 'Ära jäta eneses peituvat armuannet hooletusse, mis sulle anti ennustuse läbi, kui vanemad panid oma käed sinu peale.',
        15: 'Seda harrasta, selles ela, et sinu edenemine oleks ilmne kõikidele.',
        16: 'Pane tähele iseennast ja õpetust; püsi kindlasti selles; sest kui sa seda teed, päästad sa enese ja need, kes sind kuulevad.',
    },
    5: {
        1: 'Vana meest ära sõitle valjusti, vaid manitse teda kui isa, nooremaid kui vendi,',
        2: 'vanemaid naisi kui emasid, nooremaid kui õdesid kõiges meelepuhtuses.',
        3: 'Austa leski, kes on õiged lesknaised.',
        4: 'Aga kui kellelgi lesel on lapsi või lapselapsi, siis õppigu need esiti vagalt kohtlema oma majarahvast ja tasuma, mis nad on võlgu oma vanemaile. Sest see on meelepärane Jumala ees.',
        5: 'Aga kes õige lesk on ja üksi maha jäänud, see loodab Jumala peale ja jääb kindlasti anumistesse ja palvetesse ööd ja päevad.',
        6: 'Aga kes elab lihahimus, see on elusalt surnud.',
        7: 'Ja sedagi pane südamele, et nad oleksid laitmatud.',
        8: 'Aga kui keegi enese omaste ja iseäranis kodakondsete eest ei kanna hoolt, see on usu ära salanud ja on pahem kui uskmatu.',
        9: 'Leskede hulka loetagu ainult niisugune, kes on vähemalt kuuskümmend aastat vana ja on olnud ühe mehe naine,',
        10: 'ja kes on tunnustatud heade tegude poolest, kui ta on kasvatanud lapsi, kui ta on vastu võtnud võõraid, kui ta on pühade jalgu pesnud, kui ta on aidanud hädasolijaid, kui ta on püüdnud teha kõiksugust head.',
        11: 'Kuid nooremaid leski keeldu vastu võtmast, sest kui iharus neid Kristuse kiuste vallutab, siis nad tahavad minna mehele,',
        12: 'ja neid tuleb süüdistada selles, et nad on hüljanud esimese usu.',
        13: 'Kui nad on pealegi jõude, harjuvad nad käima mööda maju, ja siis ei ole nad mitte ainult jõude, vaid ka lobisejad ning uudishimulikud ja räägivad sobimatuid asju.',
        14: 'Ma tahan siis, et nooremad läheksid mehele ja tooksid lapsi ilmale, valitseksid majatalitusi ega annaks vastasele põhjust solvamiseks.',
        15: 'Sest mõned ongi juba pöördunud saatana jälgedesse.',
        16: 'Kui kellelgi usklikul mehel või naisel on leski omaste seas, siis nad hooldagu neid ja ärgu saagu need koormaks Kogudusele, et see võiks hooldada tõelisi leski.',
        17: 'Vanemaid, kes hästi juhatavad Kogudusi, peetagu kahekordse austuse vääriliseks, eriti neid, kes töötavad sõnas ja õpetuses.',
        18: 'Sest Kiri ütleb: "Ära seo kinni härja suud, kui ta pahmast tallab!" ja: "Töötegija on oma palga väärt!"',
        19: 'Vanema vastu tõstetud kaebust ära võta kuulda, kui ei ole juures kaht või kolme tunnistajat.',
        20: 'Kes pattu teevad, neid noomi kõikide ees, et ka teistel oleks hirm.',
        21: 'Ma vannutan sind Jumala ja Kristuse Jeesuse ja äravalitud inglite ees, et sa seda pead silmas ilma eelarvamiseta ega tee midagi erapoolikult.',
        22: 'Ära ole kärmas kellelegi käsi pea peale panema ja ära tee ennast teiste pattude osaliseks. Pea ennast puhtana.',
        23: 'Ära joo enam ainult vett, vaid tarvita pisut viina oma kõhu pärast ja oma sageda põdemise pärast.',
        24: 'Mõnede inimeste patud on kohe avalikud ja on kohe hukkamõistetavad, aga mõnede omad saavad tagantjärele ilmsiks.',
        25: 'Samuti on ka head teod kohe avalikud, ja needki, mis seda ei ole, ei või jääda varjule.',
    },
    6: {
        1: 'Kõik need, kes on orjaikke all, pidagu oma isandaid kõige austuse väärt, et Jumala nime ja õpetust ei pilgataks.',
        2: 'Aga kellel on usklikud isandad, ärgu pidagu neid halvemaks, sellepärast et nad on vennad, vaid orjaku neid veel parema meelega, sest et nad on usklikud ja armsad ning harrastavad heategevust. Seda õpeta ja manitse.',
        3: 'Kui keegi õpetab teisiti ega hoia meie Issanda Jeesuse Kristuse tervete sõnade ja õpetuse poole, mis viib jumalakartusele,',
        4: 'siis on see iseennast täis ega saa aru millestki, vaid on haige küsimuste ja vaidlemiste poolest, millest tõuseb kadedust, riidu, laimu, kurje kahtlusi,',
        5: 'alalisi tülitsusi inimeste vahel, kelle mõistus on rikutud ja kellel on tõde läinud käest, kes peavad jumalakartust tuluallikaks.',
        6: 'Ent jumalakartus on suur tuluallikas, kui ta on ühendatud rahulolemisega.',
        7: 'Ei ole me ju midagi toonud maailma, seepärast me ei või midagi siit ära viia.',
        8: 'Aga kui meil on peatoidust ja ihukatet, siis olgem sellega rahul.',
        9: 'Ent kes tahavad rikkaks saada, need langevad kiusatusse ja võrku ja paljudesse rumalaisse ja kahjulikesse himudesse, mis suruvad inimesed alla hukatusse ja hävitusse.',
        10: 'Sest rahaahnus on kõigi kurjade asjade juur; raha ihaldades on mitmed ära eksinud usust ja on iseendile valmistanud palju torkavat valu.',
        11: 'Aga sina, Jumala inimene, põgene selle eest! Taotle õigust, jumalakartust, usku, armastust, kannatlikkust, tasadust!',
        12: 'Võitle head usuvõitlust, hakka kinni igavesest elust; selleks sa oled kutsutud ja oled tunnistanud head tunnistust paljude tunnistajate ees.',
        13: 'Ma käsin sind Jumala ees, Kes kõik teeb elavaks, ja Kristuse Jeesuse ees, Kes Pontius Pilaatuse ees andis hea tunnistuse,',
        14: 'et sa peaksid käsku kinni veatult ja laitmatult kuni meie Issanda Jeesuse Kristuse ilmumiseni,',
        15: 'mille omal ajal toob nähtavale õnnis ja ainus vägev valitseja, kuningate Kuningas ja kõigi isandate Issand,',
        16: 'Kellel üksi on surematus, Kes elab ligipääsmatus valguses, Keda ükski inimene ei ole näinud ega võigi näha! Temale olgu austus ja igavene vägi! Aamen.',
        17: 'Neid, kes on rikkad selles maailmas, manitse mitte olla suurelised ega loota kaduva rikkuse peale, vaid elava Jumala peale, Kes meile annab kõike rohkesti tarvituseks,',
        18: 'teha head ja rikkaks saada heade tegude poolest, olla helde käega ning jagada teistele',
        19: 'ja koguda enestele raudvara heaks aluseks tuleviku jaoks, et saavutada tõelist elu.',
        20: 'Oh Timoteos! Hoia enda hooleks antud vara ning pöördu ära kõlvatuist tühjest juttudest ja valenimelise tunnetuse väidetest,',
        21: 'mida mõningad kiidavad enestel olevat ning on ära eksinud usust. Arm teiega!',
    },
}
